	private SailDataset observeDataset(IsolationLevel level, SailDataset base, SnapshotLease lease)
			throws SailException {
		SailDataset derivedFrom = base;
		if (lease != null) {
			derivedFrom = new DelegatingSailDataset(base) {
				@Override
				public void close() {
					// The shared snapshot is closed only after its final observer releases the lease.
				}
			};
		}
		Iterator<Changeset> iter = changes.iterator();
		while (iter.hasNext()) {
			derivedFrom = new SailDatasetImpl(derivedFrom, iter.next());
		}
		if (serializable != null) {
			derivedFrom = new ObservingSailDataset(derivedFrom, sink(level));
		}

		SailDataset dataset = new DelegatingSailDataset(derivedFrom) {
			private final AtomicBoolean closed = new AtomicBoolean();

			@Override
			public void close() throws SailException {
				if (!closed.compareAndSet(false, true)) {
					return;
				}

				Throwable failure = null;
				try {
					super.close();
				} catch (RuntimeException | Error closeFailure) {
					failure = closeFailure;
				}

				try {
					semaphore.lock();
					try {
						observers.remove(this);
						SnapshotLease borrowedSnapshot = observerSnapshots.remove(this);
						if (borrowedSnapshot != null) {
							try {
								releaseSnapshot(borrowedSnapshot);
							} catch (RuntimeException | Error cleanupFailure) {
								failure = addFailure(failure, cleanupFailure);
							}
						}
						try {
							compressChanges();
						} catch (RuntimeException | Error cleanupFailure) {
							failure = addFailure(failure, cleanupFailure);
						}
					} finally {
						semaphore.unlock();
					}
				} catch (RuntimeException | Error cleanupFailure) {
					failure = addFailure(failure, cleanupFailure);
				}

				try {
					autoFlush();
				} catch (RuntimeException | Error cleanupFailure) {
					failure = addFailure(failure, cleanupFailure);
				}

				if (failure != null) {
					rethrow(failure);
				}
			}
		};
		observers.add(dataset);
		if (lease != null) {
			lease.borrowers++;
			observerSnapshots.put(dataset, lease);
		}
		return dataset;
	}

	private boolean isSnapshotUsable(SailDataset dataset, IsolationLevel level) {
		if (!dataset.isSnapshotCompatibleWithCurrentAdmission()) {
			return false;
		}
		return level.isCompatibleWith(IsolationLevels.SNAPSHOT) || backingSource.isSnapshotCurrent(dataset);
	}

	private void awaitSnapshotAdmission(SnapshotAdmission admission) throws SailException {
		try {
			admission.completed.await();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new SailException("Interrupted while waiting for a snapshot generation", e);
		}
		if (admission.failure != null) {
			rethrow(admission.failure);
		}
	}

	private void completeSnapshotAdmission(SnapshotAdmission admission, Throwable failure) {
		semaphore.lock();
		try {
			if (snapshotAdmission == admission) {
				if (!admission.invalidated && admission.generation == snapshotGeneration) {
					admission.failure = failure;
				}
				snapshotAdmission = null;
			}
		} finally {
			semaphore.unlock();
		}
		admission.completed.countDown();
	}

	private static Throwable addFailure(Throwable failure, Throwable later) {
		if (failure == null) {
			return later;
		}
		if (failure != later) {
			failure.addSuppressed(later);
		}
		return failure;
	}

	private static Throwable closeResource(Throwable failure, SailClosable resource) {
		if (resource != null) {
			try {
				resource.close();
			} catch (RuntimeException | Error closeFailure) {
				return addFailure(failure, closeFailure);
			}
		}
		return failure;
	}

	private static void rethrow(Throwable failure) throws SailException {
		if (failure instanceof SailException sailException) {
			throw sailException;
		}
		if (failure instanceof RuntimeException runtimeException) {
			throw runtimeException;
		}
		throw (Error) failure;
	}

